"""THE RED SEA AND BAB EL-MANDEB -- Yemen, Djibouti, Sudan, Eritrea and Somalia: one strait, five
treasuries, and the largest peacetime reordering of global shipping in decades.

WHY FIVE JURISDICTIONS IN ONE PACK, AND WHY THESE FIVE. They are not "the countries nobody
covers". They are the two shores and the hinterland of ONE PHYSICAL ASSET -- the Bab el-Mandeb
strait -- through which roughly 12% of world trade and 8-10% of seaborne oil moved before
November 2023. Yemen owns the eastern shore and the islands in the channel; Djibouti and Eritrea
own the western shore; Somalia owns the water the traffic must cross to reach it and supplied the
piracy history that made the whole passage an insurance problem in the first place; and Sudan
owns the Red Sea's western coast, the outlet for South Sudanese crude and the acacia belt that
supplies most of the world's gum arabic. Splitting them would split the mechanism. Egypt (`eg`)
owns the OTHER END of the same waterway and is answered by its own pack: the Suez Canal
Authority's transit counts and Egypt's canal revenue are the published measure of what this
pack's disruptions cost, which is why `eg` is named FIRST in INTERACTIONS and why this pack never
measures the Suez half alone.

THE EVENT THAT EARNS THE TRIAL BUDGET IS DATED, PUBLISHED AND STILL RUNNING. From 2023-11-19,
when the Galaxy Leader was seized, attacks on shipping in the southern Red Sea drove the major
container lines out of the strait; Suez transits fell by more than half, Egypt's canal revenue
fell by roughly 60% in 2024 on the Suez Canal Authority's own numbers, and the Asia-Europe trade
rerouted around the CAPE OF GOOD HOPE -- adding roughly 10-14 days and thousands of nautical
miles to every voyage. That is not a narrative. It is a daily transit count published by the IMF
PortWatch project, a monthly navigation statistic published by the Suez Canal Authority, a
chokepoint volume published by the EIA, a set of freight indices published weekly, and a war-risk
premium quoted in public market commentary. And its consequences run straight into instruments
this desk executes: XBRUSD and XTIUSD through voyage length and tanker tonne-mile demand, XNGUSD
through LNG rerouting, the European risk complex through freight-cost pass-through, and the softs
and grains that pay the freight.

PANAMA IS THE CONTROL, AND IT IS THE CLEANEST ONE AVAILABLE. In the SAME eighteen months a second
great chokepoint was constrained for a COMPLETELY UNRELATED reason: the Panama Canal Authority cut
daily transits from about 36 to a low near 22-24 because Gatun Lake was too low, and restored them
through 2024 as the rains returned. Drought and conflict share no cause, no actor and no
announcement calendar, so a freight or crude response common to BOTH is a chokepoint-constraint
effect and a response present in only one is a Red Sea effect or a Panama effect. RS-A is built
on that identification and every chokepoint domain in this file names Panama in its controls.

THE FIVE MECHANISMS, ONE PER JURISDICTION, EACH PUBLISHED AND DATED:

  1. YEMEN HAS TWO CENTRAL BANKS AND TWO PUBLISHED EXCHANGE RATES FOR ONE CURRENCY. The Central
     Bank of Yemen was relocated to Aden by decree on 2016-09-18, the Sana'a authorities banned
     the newly printed banknotes in December 2019, and since then the two rials have traded at
     wildly different rates -- the Aden rial past 1,600 to the dollar while the Sana'a rial was
     held near 530-560. One country, two banknote series, two quoted rates, and the SPREAD
     BETWEEN THEM is a published, high-frequency conflict-intensity observable that exists almost
     nowhere else on earth. Yemen also stopped exporting crude after the attacks on the Ash Shihr
     and Rudum loading terminals in October and November 2022, and the humanitarian import
     corridor through Hodeidah is measured by UNVIM's published vessel-clearance statistics.
  2. DJIBOUTI IS THE SMALLEST JURISDICTION HERE AND THE MOST SYSTEMICALLY IMPORTANT. It is
     ETHIOPIA'S ONLY PORT -- more than 95% of the trade of a landlocked country of well over a
     hundred million people -- and it hosts the foreign military bases of the United States,
     China, France, Japan and Italy on one small piece of coast. Its franc is a CURRENCY BOARD
     PEGGED AT 177.721 TO THE DOLLAR SINCE 1973, one of the longest unbroken pegs on earth, with
     foreign assets covering the monetary base. That peg makes Djibouti the CONTROL jurisdiction
     for every floating and collapsing neighbour in this pack: when four currencies move and one
     cannot, what moves is not the currency. The Addis-Djibouti railway, the DP World Doraleh
     concession dispute of 2018 and the port's published throughput are the physical series, and
     the Ethiopian half of that system belongs to the `east_africa` pack.
  3. SUDAN IS THE WORLD'S DOMINANT SOURCE OF GUM ARABIC -- roughly 70-80% of global supply from
     the acacia belt of Kordofan, Darfur and Blue Nile -- an input with no adequate substitute in
     soft drinks, confectionery and pharmaceuticals. The war that began on 2023-04-15 disrupted
     it on a dated, published timeline. Sudan also exports gold, much of it through the United
     Arab Emirates and therefore visible in MIRROR customs statistics (an interaction with `ae`),
     and Port Sudan is the outlet for SOUTH SUDANESE CRUDE, whose pipeline ruptured in February
     2024 and halted roughly 150,000 b/d for months. The pound's collapse and the central bank's
     relocation to Port Sudan are dated events.
  4. ERITREA IS THE PACK'S HONEST LIMIT CASE AND ITS MOST VALUABLE OUTPUT. It is one of the most
     closed economies on earth: it publishes almost no national statistics, has no securities
     exchange, no published market rate for the nakfa, no independent domestic academic
     economics and no retail trading ecology at all. That is a MEASUREMENT, not a gap, and this
     pack declares each absent layer BY NAME with the LAWFUL SUBSTITUTE that carries the
     information instead -- mirror customs from China, the UAE and India, the operators' public
     filings for Bisha and Colluli, IMF and UN agency reporting, and satellite-derived port and
     night-light series published by research institutions. A measured NO_LAWFUL_GROUND row with
     a named substitute is worth more than any padded source list, and Eritrea contributes six.
  5. SOMALIA IS WHY THE PASSAGE WAS INSURABLE IN THE FIRST PLACE. The piracy epidemic that peaked
     around 2011 built the war-risk architecture -- the Listed Areas, the naval escorts, the armed
     guards -- that the 2023-2025 attacks then priced against, and piracy RESUMED in late 2023
     alongside them, which is a genuine confound a study must separate. Somali livestock exports
     to the Gulf run on a HAJJ-LINKED SEASONAL CLOCK that moves eleven days earlier each solar
     year (an interaction with `sa` and `gulf`), Berbera and the Ethiopia-Somaliland memorandum of
     2024-01-01 are dated geopolitical events, and the shilling circulates with no functioning
     issuing authority while MOBILE MONEY IS THE MONETARY SYSTEM.

FIVE CURRENCIES, FIVE ABSENCES, AND THE PACK SAYS SO FIVE TIMES. YER, DJF, SDG, ERN and SOS are
none of them in `data/universe/universe.json` and never will be. Every one is named in
`TRANSMISSION_TARGETS` with its regime, its parallel or split rate, and the broker symbols its
economics route into, so an absent instrument produces a transmission hypothesis and never a cell
that can never be filled (L1.49). FREIGHT IS THE SAME PROBLEM AND GETS THE SAME TREATMENT: the
container and tanker rate indices, the war-risk premium, gum arabic and potash are not broker
symbols, so each is routed explicitly with its control named, and the pack is blunt that freight
is the TRANSMISSION while the executable leg is the commodity.

THE GROUND IS ARABIC, FRENCH, TIGRINYA AND SOMALI, AND AN ENGLISH CRAWL READS THE WRONG HALF OF
ALL FOUR. The two Yemeni central banks argue in ARABIC and so do Sudan's, Djibouti's official
notices and the regional press; Djibouti legislates and reports in FRENCH and its Journal Officiel
and port filings are French documents; Eritrea's state outlet and its ministries publish in
TIGRINYA in the Ge'ez script; and Somalia's ports, livestock trade, piracy reporting and mobile
money are argued in SOMALI. The terminology table and every source class's queries are written in
those four languages for exactly that reason.

ACCESS AND LAWFULNESS ARE NOT AN AFTERTHOUGHT HERE. Several of these jurisdictions are under
sanctions regimes and several are active conflict zones. NOTHING in this pack touches any entity's
private systems and nothing bypasses an access control: everything here is PUBLIC -- national
statistics where they exist, UN and IMF publications, IMF PortWatch and UNCTAD transit series,
EIA, the Suez Canal Authority's own numbers, published court and administrative records, and
public press. Sanctions constrain TRANSACTIONS, not the reading of published statistics, and the
desk executes only broker symbols and never an instrument of any of these five countries. Nothing
here collects personal data about any individual, and no conflict-casualty or humanitarian dataset
is used for anything but the dated event boundaries it establishes. The whole of it is in
`ACCESS_CONSTRAINTS`, row by row.

THE TWO-LANE ORDER (2026-09-06) BINDS. The tempting names here are all single companies -- the
container lines, the terminal operators, the mine operators, the mobile-money networks -- and each
one appears in this pack as an ACTOR and never as an instrument. No share CFD appears in any
instrument tuple in this file, and no crypto-exchange ground is hunted (mandate 2026-08-18).
"""
from __future__ import annotations

