# ------------------------------------------------------- the split weekend and the two calendars
#: THE DISTINGUISHING CALENDAR FACT OF THIS PACK, and the one a study gets wrong by default.
#: FOUR of the five neighbours keep a FRIDAY-SATURDAY weekend and work SUNDAY TO THURSDAY; the
#: fifth, ERITREA, keeps a SATURDAY-SUNDAY weekend and works MONDAY TO FRIDAY, because it is
#: roughly half Christian and half Muslim and settled on the Western week. So:
#:
#:   * SUNDAY is a full business day in Yemen, Djibouti, Sudan and Somalia and a weekend day in
#:     Eritrea and in London and New York.
#:   * FRIDAY is a weekend day in four of the five and a full business day in Eritrea and in
#:     every market this desk executes in.
#:   * SATURDAY is the only day closed in all five.
#:
#: A study that assumes a Saturday-Sunday weekend misaligns FOUR of these five jurisdictions and
#: reads their busiest announcement day as a non-day. Python weekdays: Monday=0 ... Sunday=6.
WEEKEND_DAYS: dict[str, tuple[int, ...]] = {
    "ye": (4, 5),   # Friday, Saturday
    "dj": (4, 5),   # Friday, Saturday
    "sd": (4, 5),   # Friday, Saturday
    "so": (4, 5),   # Friday, Saturday
    "er": (5, 6),   # Saturday, Sunday -- alone among the five
}
WORKING_WEEK: dict[str, str] = {
    "ye": "Sunday to Thursday", "dj": "Sunday to Thursday", "sd": "Sunday to Thursday",
    "so": "Sunday to Thursday", "er": "Monday to Friday",
}
#: The only weekday closed in every one of the five at once. Everything else is a working day
#: somewhere in this pack, which is why `market_holidays` cannot use a single weekend rule.
UNIVERSAL_CLOSED_WEEKDAY: int = 5


def is_weekend(code: str, day: date) -> bool:
    """True when `day` is a weekend day in THIS jurisdiction. Four say Friday-Saturday and
    Eritrea says Saturday-Sunday; there is no pack-wide answer and pretending there is one is
    the error this function exists to make impossible."""
    return day.weekday() in WEEKEND_DAYS.get(str(code).lower(), (5, 6))


def working_jurisdictions(day: date) -> tuple[str, ...]:
    """Which of the five are AT WORK on a given date, in declaration order.

    A Sunday returns the four Sunday-Thursday countries and not Eritrea; a Friday returns
    Eritrea alone; a Saturday returns nothing. This is the pack's cleanest calendar object: it
    turns the split weekend from a footnote into a series a cell can condition on.
    """
    return tuple(code for code in JURISDICTIONS if not is_weekend(code, day))


def working_week(code: str) -> str:
    return WORKING_WEEK.get(str(code).lower(), "Monday to Friday")


# --------------------------------------------------------------------------- the Julian computus
#: Gregorian ordinal 1 (1 January 1 CE, proleptic) is Julian Day Number 1721426, so the ordinal
#: of a JDN is `jdn - 1721425`. Eritrea's Orthodox feasts are JULIAN dates and converting them by
#: "add thirteen days" is right for this century and wrong as a rule, so the conversion goes
#: through the day number instead.
_JDN_OF_ORDINAL_ZERO = 1721425


def julian_to_gregorian(year: int, month: int, day: int) -> date:
    """A JULIAN calendar date as the Gregorian date the same moment falls on.

    Ldet (Christmas, 25 December Julian) and Timket (Epiphany, 6 January Julian) are FIXED in the
    Julian calendar, which is exactly why they land on 7 and 19 January Gregorian throughout this
    century -- and why a pack that types them as fixed Gregorian dates is right until 2100 and
    wrong for the reason it thinks it is right.
    """
    a = (14 - int(month)) // 12
    y = int(year) + 4800 - a
    m = int(month) + 12 * a - 3
    jdn = int(day) + (153 * m + 2) // 5 + 365 * y + y // 4 - 32083
    return date.fromordinal(jdn - _JDN_OF_ORDINAL_ZERO)


def orthodox_easter(year: int) -> date:
    """Fasika, by MEEUS' JULIAN algorithm, converted through the Julian day number.

    Eritrea's Orthodox Tewahedo Easter is computed on the Julian computus, so it drifts against
    the Western Easter and coincides with it only occasionally. It is arithmetic and never a
    sighting, which is why this pack computes it and types only the Islamic feasts.
    """
    y = int(year)
    a, b, c = y % 4, y % 7, y % 19
    d = (19 * c + 15) % 30
    e = (2 * a + 4 * b - d + 34) % 7
    month = (d + e + 114) // 31
    day = ((d + e + 114) % 31) + 1
    return julian_to_gregorian(y, month, day)


def ldet(year: int) -> date:
    """Eritrean Orthodox Christmas: 25 December JULIAN, so 7 January Gregorian this century."""
    return julian_to_gregorian(year - 1, 12, 25)


def timket(year: int) -> date:
    """Epiphany: 6 January JULIAN, which is 19 January Gregorian this century."""
    return julian_to_gregorian(year, 1, 6)


def geez_new_year(year: int) -> date:
    """Kudus Yohannes, the Ge'ez new year Eritrea shares with Ethiopia: 11 September, or 12
    September in the year FOLLOWING a Ge'ez leap year.

    Ge'ez year N is leap when N mod 4 == 3 and Gregorian year G contains the start of Ge'ez year
    G-7, so the preceding Ge'ez year G-8 is leap exactly when G mod 4 == 3. The alternation is
    what a typed table gets wrong, which is why this is a function.
    """
    return date(int(year), 9, 12 if int(year) % 4 == 3 else 11)


def meskel(year: int) -> date:
    """Meskel, sixteen days after the Ge'ez new year, so it alternates 27/28 September."""
    return geez_new_year(year) + timedelta(days=16)


# --------------------------------------------------------------------------- national calendars
#: FIXED SOLAR HOLIDAYS, per jurisdiction. Rows are (month, day, name). None of the five
#: substitutes a weekend holiday onto the next working day as a rule, so a holiday that lands on
#: a local weekend costs no session -- and because the local weekends DIFFER, the same date can
#: cost a session in one of these countries and nothing in its neighbour.
FIXED_YE: tuple[tuple[int, int, str], ...] = (
    (1, 1, "New Year / رأس السنة الميلادية"),
    (5, 1, "Labour Day / عيد العمال"),
    (5, 22, "Yemeni Unity Day / عيد الوحدة اليمنية"),
    (9, 26, "26 September Revolution / ثورة 26 سبتمبر"),
    (10, 14, "14 October Revolution / ثورة 14 أكتوبر"),
    (11, 30, "Independence Day / عيد الجلاء"),
)
FIXED_DJ: tuple[tuple[int, int, str], ...] = (
    (1, 1, "New Year / Jour de l'An"),
    (5, 1, "Labour Day / Fete du Travail"),
    (6, 27, "Independence Day / Fete de l'Independance"),
    (6, 28, "Independence Day second day / Fete de l'Independance"),
)
FIXED_SD: tuple[tuple[int, int, str], ...] = (
    (1, 1, "Independence Day / عيد الاستقلال"),
    (1, 7, "Coptic Christmas / عيد الميلاد القبطي"),
    (12, 25, "Christmas / عيد الميلاد"),
)
FIXED_ER: tuple[tuple[int, int, str], ...] = (
    (1, 1, "New Year"),
    (2, 10, "Fenkil Day (the liberation of Massawa) / ፈንቅል"),
    (3, 8, "International Women's Day"),
    (5, 1, "Workers' Day"),
    (5, 24, "Independence Day / ናጽነት"),
    (6, 20, "Martyrs' Day / ዕለተ ሰማእታት"),
    (9, 1, "Start of the Armed Struggle / ባሕቲ መስከረም"),
)
FIXED_SO: tuple[tuple[int, int, str], ...] = (
    (1, 1, "New Year / Sannad Cusub"),
    (5, 1, "Labour Day / Maalinta Shaqaalaha"),
    (5, 18, "Somaliland Declaration Day (observed in Somaliland only) / 18 Maajo"),
    (6, 26, "Independence of the North (1960) / Maalinta Xornimada"),
    (7, 1, "Republic Day (the 1960 union) / Maalinta Jamhuuriyadda"),
)

#: THE ISLAMIC FEASTS ARE TYPED, WITH THE AUTHORITY THAT SIGHTS THEM IN EACH COUNTRY, because no
#: weekday rule computes a moon sighting and a wrong rule is worse than an honest table. SIX
#: bodies announce across five countries and they do not always agree: Aden and Sana'a have
#: announced Eid on DIFFERENT DAYS inside Yemen, and Somaliland announces separately from
#: Mogadishu. Rows are (date, name, status).
LUNAR_HOLIDAYS: dict[int, tuple[tuple[date, str, str], ...]] = {
    2024: ((date(2024, 4, 10), "Eid al-Fitr / عيد الفطر / Ciid al-Fitr", "ANNOUNCED"),
           (date(2024, 6, 16), "Eid al-Adha / عيد الأضحى / Ciid al-Adha", "ANNOUNCED"),
           (date(2024, 7, 7), "Islamic New Year / رأس السنة الهجرية", "ANNOUNCED"),
           (date(2024, 7, 17), "Ashura / عاشوراء", "ANNOUNCED"),
           (date(2024, 9, 16), "Mawlid an-Nabi / المولد النبوي", "ANNOUNCED")),
    2025: ((date(2025, 3, 31), "Eid al-Fitr / عيد الفطر / Ciid al-Fitr", "ANNOUNCED"),
           (date(2025, 6, 7), "Eid al-Adha / عيد الأضحى / Ciid al-Adha", "ANNOUNCED"),
           (date(2025, 6, 26), "Islamic New Year / رأس السنة الهجرية", "ANNOUNCED"),
           (date(2025, 7, 6), "Ashura / عاشوراء", "ANNOUNCED"),
           (date(2025, 9, 5), "Mawlid an-Nabi / المولد النبوي", "PROJECTED")),
    2026: ((date(2026, 3, 20), "Eid al-Fitr / عيد الفطر / Ciid al-Fitr", "PROJECTED"),
           (date(2026, 5, 27), "Eid al-Adha / عيد الأضحى / Ciid al-Adha", "PROJECTED"),
           (date(2026, 6, 16), "Islamic New Year / رأس السنة الهجرية", "PROJECTED"),
           (date(2026, 6, 25), "Ashura / عاشوراء", "PROJECTED"),
           (date(2026, 8, 25), "Mawlid an-Nabi / المولد النبوي", "PROJECTED")),
}
#: Which of the five actually close for which lunar feast. Ashura is a closure in Yemen, Sudan,
#: Djibouti and Somalia and not in Eritrea; the Islamic New Year is not a closure in Yemen.
LUNAR_OBSERVANCE: dict[str, tuple[str, ...]] = {
    "ye": ("Eid al-Fitr", "Eid al-Adha", "Ashura", "Mawlid"),
    "dj": ("Eid al-Fitr", "Eid al-Adha", "Islamic New Year", "Ashura", "Mawlid"),
    "sd": ("Eid al-Fitr", "Eid al-Adha", "Islamic New Year", "Mawlid"),
    "er": ("Eid al-Fitr", "Eid al-Adha", "Mawlid"),
    "so": ("Eid al-Fitr", "Eid al-Adha", "Islamic New Year", "Ashura", "Mawlid"),
}
#: WHO SIGHTS THE MOON, per jurisdiction. Six bodies, five countries, and two of the countries
#: contain two announcing authorities apiece.
SIGHTING_AUTHORITIES: dict[str, str] = {
    "ye": "the judicial authority in ADEN and the authority in SANA'A announce SEPARATELY and "
          "have declared Eid on different days inside one country -- the same split that runs "
          "through the currency",
    "dj": "the Ministry of Muslim Affairs and the Grand Cadi of Djibouti",
    "sd": "the moon-sighting committee under the Ministry of Guidance and Religious Endowments, "
          "announcing from Port Sudan since 2023",
    "er": "the Office of the Mufti of Eritrea; Eritrea observes the two Eids and Mawlid and does "
          "NOT close for Ashura, which is a real per-country asymmetry",
    "so": "the Ministry of Religious Affairs and Endowments in Mogadishu, with SOMALILAND "
          "announcing separately from Hargeisa",
}
#: One-off dated facts no recurring rule produces. Not all of them are closures; each says which.
DECLARED_CLOSURES: dict[date, str] = {
    date(2024, 1, 1): "the Ethiopia-Somaliland memorandum of understanding on port and coastal "
                      "access was signed -- not a closure, carried here as the dated "
                      "geopolitical fact RS-Q conditions on",
    date(2023, 4, 15): "the outbreak of war in Sudan and the suspension of the Khartoum Stock "
                       "Exchange -- an era boundary rather than a holiday",
}


def _lunar_rows(code: str, year: int) -> dict[date, str]:
    """The lunar closures THIS jurisdiction actually keeps, with the status kept on the row."""
    wanted = LUNAR_OBSERVANCE.get(str(code).lower(), ())
    out: dict[date, str] = {}
    for day, name, status in LUNAR_HOLIDAYS.get(int(year), ()):
        if any(w in name for w in wanted):
            out[day] = f"{name} [{status}]"
    return out


def yemeni_holidays(year: int) -> dict[date, str]:
    """Yemen's closed days: six fixed solar dates and four Islamic feasts.

    THE TABLE IS THE INTERNATIONALLY RECOGNISED CALENDAR and the pack says so: the authorities in
    Sana'a do not observe every republican anniversary in this list and observe 21 September,
    which Aden does not. A closure study on Yemen that pools the two areas is pooling two states.
    """
    out = {date(year, m, d): name for m, d, name in FIXED_YE}
    out.update(_lunar_rows("ye", year))
    return dict(sorted(out.items()))


def djiboutian_holidays(year: int) -> dict[date, str]:
    """Djibouti's closed days: four fixed solar dates and five Islamic feasts."""
    out = {date(year, m, d): name for m, d, name in FIXED_DJ}
    out.update(_lunar_rows("dj", year))
    return dict(sorted(out.items()))


def sudanese_holidays(year: int) -> dict[date, str]:
    """Sudan's closed days: Independence Day on 1 January, the two Christmases and four Islamic
    feasts. Since 2023 the announcements are made from Port Sudan."""
    out = {date(year, m, d): name for m, d, name in FIXED_SD}
    out.update(_lunar_rows("sd", year))
    return dict(sorted(out.items()))


def eritrean_holidays(year: int) -> dict[date, str]:
    """Eritrea's closed days: seven fixed solar dates, the ORTHODOX movable feasts COMPUTED from
    the Julian computus and the Ge'ez calendar, and the three Islamic feasts it keeps.

    Eritrea is the only one of the five that carries BOTH calendars as public holidays, and the
    only one with a Saturday-Sunday weekend. Ldet, Timket, Kudus Yohannes and Meskel are all
    computed here and none of them is typed.
    """
    out: dict[date, str] = {
        ldet(year): "Ldet (Orthodox Christmas) / ልደት",
        timket(year): "Timket (Epiphany) / ጥምቀት",
        geez_new_year(year): "Kudus Yohannes (Ge'ez New Year) / ቅዱስ ዮሃንስ",
        meskel(year): "Meskel (Finding of the True Cross) / መስቀል",
    }
    fasika = orthodox_easter(year)
    out[fasika - timedelta(days=2)] = "Good Friday / ዓርቢ ስቅለት"
    out[fasika] = "Fasika (Orthodox Easter) / ፋሲካ"
    for m, d, name in FIXED_ER:
        out[date(year, m, d)] = name
    out.update(_lunar_rows("er", year))
    return dict(sorted(out.items()))


def somali_holidays(year: int) -> dict[date, str]:
    """Somalia's closed days: five fixed solar dates and five Islamic feasts.

    18 May is observed in SOMALILAND ONLY and 26 June and 1 July are the two halves of the 1960
    union; carrying all three is the honest way to hold one calendar for two administrations.
    """
    out = {date(year, m, d): name for m, d, name in FIXED_SO}
    out.update(_lunar_rows("so", year))
    return dict(sorted(out.items()))


JURISDICTION_HOLIDAY_FN: dict[str, Any] = {
    "ye": yemeni_holidays, "dj": djiboutian_holidays, "sd": sudanese_holidays,
    "er": eritrean_holidays, "so": somali_holidays,
}


def national_holidays(year: int) -> dict[date, str]:
    """EVERY closed day in the five, tagged with the countries that actually close.

    A union table, because this pack answers for five countries at once and a day that closes
    Asmara is a full business day in Aden. The tag is what keeps a study from reading a
    one-country closure as a regional one.
    """
    tagged: dict[date, list[str]] = {}
    names: dict[date, str] = {}
    for code, fn in JURISDICTION_HOLIDAY_FN.items():
        for day, name in fn(year).items():
            tagged.setdefault(day, []).append(code.upper())
            names.setdefault(day, name)
    out = {day: f"{names[day]} [{'+'.join(sorted(codes))}]" for day, codes in tagged.items()}
    for day, name in DECLARED_CLOSURES.items():
        if day.year == year:
            out[day] = f"{out.get(day, '')} {name}".strip()
    return dict(sorted(out.items()))


def market_holidays(year: int) -> dict[date, str]:
    """The closures that actually COST A SESSION somewhere in the five.

    This cannot be "drop the weekends" because the five do not share a weekend. A day is kept
    when at least one jurisdiction closes for it AND that jurisdiction would otherwise have been
    at work -- so an Eid that falls on a Friday still costs Eritrea a day and costs the other
    four nothing, and the table says so instead of dropping the row.
    """
    out: dict[date, str] = {}
    for day, label in national_holidays(year).items():
        closers = [c for c, fn in JURISDICTION_HOLIDAY_FN.items()
                   if day in fn(year) and not is_weekend(c, day)]
        if closers:
            out[day] = label
    return out


def is_market_holiday(day: date) -> bool:
    return day in market_holidays(day.year)


def closed_in(code: str, day: date) -> bool:
    """True when THIS jurisdiction is closed on this day -- by holiday OR by its own weekend."""
    key = str(code).lower()
    if is_weekend(key, day):
        return True
    fn = JURISDICTION_HOLIDAY_FN.get(key)
    return day in fn(day.year) if fn is not None else False


def announced_dates(year: int) -> dict[date, str]:
    """Only the Islamic feasts that were ANNOUNCED. A PROJECTED row can be a day off in any of
    the five, and with six announcing authorities it can be a day off in only some of them."""
    return {d: n for d, n, st in LUNAR_HOLIDAYS.get(year, ()) if st == "ANNOUNCED"}


