# --------------------------------------------------------------------------- terminology
#: FOUR NATIVE GROUNDS AND THE PACK MEANS ALL FOUR. ARABIC is the language of both Yemeni central
#: banks, of Sudan's, of Djibouti's official notices and of the regional press, and it is the
#: lingua franca of the whole basin. FRENCH is how Djibouti legislates and reports -- the Journal
#: Officiel, the port filings and INSTAD's bulletins are French documents and an Arabic-only crawl
#: of Djibouti misses the administrative half. TIGRINYA in the Ge'ez script is Eritrea's, and it
#: is the only way into a ground that publishes nothing in English. SOMALI carries the ports, the
#: livestock trade, the piracy reporting and the mobile-money system that IS Somalia's monetary
#: system. An English-only crawl of this region returns UN press releases about it.
