#: The SOMALI marker words the terminology must actually carry. Somali is written in the LATIN
#: script, so a codepoint test cannot find it and a word list is the only honest detector.
SOMALI_MARKERS: tuple[str, ...] = (
    "burcad", "badeed", "maraakiibta", "xoolaha", "dhoofinta", "geel", "suuqa", "qiimaha",
    "dekedda", "soomaaliland", "shilin", "lacagta", "bangiga", "wasaaradda", "ganacsiga",
    "xajka", "soomaaliya", "kalluumeysiga", "amniga", "heshiiska",
)
#: The FRENCH marker words, for the same reason: Djibouti's administrative ground is French and a
#: crawl that reads only Arabic there misses the Journal Officiel and every port filing. Words
#: that are SPELLED THE SAME IN ENGLISH -- route, canal, maritime, corridor, transit, franc,
#: assurance, concession, emission, prime -- are deliberately NOT markers: including them would
#: let an English query pass as native ground, which is the exact failure this detector exists to
#: catch.
FRENCH_MARKERS: tuple[str, ...] = (
    "banque", "centrale", "djiboutien", "caisse", "parite", "taux", "couverture", "devises",
    "monnaie", "portuaire", "conteneurs", "chemin", "ethiopien", "franche", "redevances",
    "douane", "marchandises", "detroit", "navires", "guerre", "risque", "detourne", "trafic",
    "feries", "semaine", "travail",
)

# --------------------------------------------------------------------------- script detection
_ARABIC_RANGES = ((0x0600, 0x06FF), (0x0750, 0x077F), (0x08A0, 0x08FF), (0xFB50, 0xFDFF),
                  (0xFE70, 0xFEFF))
_GEEZ_RANGES = ((0x1200, 0x137F), (0x1380, 0x139F), (0x2D80, 0x2DDF), (0xAB00, 0xAB2F))

SOURCE_LAYERS: tuple[str, ...] = (
    "official", "institutional", "academic", "practitioner", "retail_ecology", "app_ecosystem",
    "media", "archive", "physical_economy", "source_graph")
ACCESS_LABELS: tuple[str, ...] = (
    "PUBLIC", "PUBLIC_WITH_TERMS", "LICENSED", "OPEN_DATA", "PUBLIC_ARCHIVE", "PUBLIC_SOCIAL",
    "USER_SUBMITTED", "ACCESS_UNCLEAR", "PRIVATE", "CONFIDENTIAL_MNPI", "STOLEN_UNAUTHORIZED")
CREDIBILITY_LABELS: tuple[str, ...] = (
    "AUTHORITATIVE", "RELIABLE", "UNRELIABLE", "FRINGE", "CONTRADICTED", "UNKNOWN")
PREDICTIVE_STATES: tuple[str, ...] = (
    "UNTESTED", "PREDICTIVE", "NOT_PREDICTIVE", "NARRATIVE_FEATURE")

_SOMALI_WORDS: frozenset[str] = frozenset(SOMALI_MARKERS)
_FRENCH_WORDS: frozenset[str] = frozenset(FRENCH_MARKERS)
_PUNCT = "-_/(),.:;!?\"'"


def _words(text: str) -> list[str]:
    return [w.strip(_PUNCT).lower() for w in str(text).replace("'", " ").split()]


def has_arabic(text: str) -> bool:
    """True when the text carries at least one Arabic codepoint. Both Yemeni central banks, the
    Sudanese one and the whole regional press argue in Arabic; a pack that spells their terms in
    English reads the English corner of the ground and reports the corner as the ground."""
    return any(any(lo <= ord(ch) <= hi for lo, hi in _ARABIC_RANGES) for ch in str(text))


def has_geez(text: str) -> bool:
    """True when the text carries at least one Ge'ez codepoint -- Eritrea's Tigrinya ground."""
    return any(any(lo <= ord(ch) <= hi for lo, hi in _GEEZ_RANGES) for ch in str(text))


def has_somali(text: str) -> bool:
    """Somali is written in the LATIN script, so it is detected by vocabulary and never by
    codepoint. A codepoint test would call every Somali phrase English and quietly conclude that
    Somalia has no native ground at all."""
    return any(w in _SOMALI_WORDS for w in _words(text))


def has_french(text: str) -> bool:
    """French, the administrative language of Djibouti, detected the same way and for the same
    reason: the Journal Officiel and the port filings are French documents."""
    return any(w in _FRENCH_WORDS for w in _words(text))


def has_native(text: str) -> bool:
    """True when a phrase is in ANY of this pack's four native grounds."""
    return has_arabic(text) or has_geez(text) or has_somali(text) or has_french(text)


def _terms(terminology: Mapping[str, Iterable[str]] | None = None) -> list[str]:
    table = TERMINOLOGY if terminology is None else terminology
    return [t for group in table.values() for t in group]


def arabic_terms(terminology: Mapping[str, Iterable[str]] | None = None) -> list[str]:
    return [t for t in _terms(terminology) if has_arabic(t)]


def geez_terms(terminology: Mapping[str, Iterable[str]] | None = None) -> list[str]:
    return [t for t in _terms(terminology) if has_geez(t)]


def somali_terms(terminology: Mapping[str, Iterable[str]] | None = None) -> list[str]:
    return [t for t in _terms(terminology) if has_somali(t)]


def french_terms(terminology: Mapping[str, Iterable[str]] | None = None) -> list[str]:
    return [t for t in _terms(terminology) if has_french(t)]


def term_count(terminology: Mapping[str, Iterable[str]] | None = None) -> int:
    """Distinct terms across every domain key of a terminology table."""
    return len(set(_terms(terminology)))


def _seq(values: Iterable[Any]) -> tuple[str, ...]:
    return tuple(str(v) for v in values)


def source_class(sid: str, label: str, *, layer: str, roots: Iterable[str],
                 queries: Iterable[str], languages: Iterable[str], access_label: str,
                 credibility: str, predictive_state: str, licence: str,
                 machine_use_allowed: bool = True, notes: str = "") -> dict[str, Any]:
    """One class of source with the roots a crawler starts from and its three INDEPENDENT labels.

    `queries` are native-script terms, never translations. `machine_use_allowed=False` registers
    ground whose terms forbid extraction: never scraped, never omitted either, because omitting
    it loses the knowledge that the ground exists.
    """
    if layer not in SOURCE_LAYERS:
        raise ValueError(f"source {sid}: layer {layer!r} not one of {list(SOURCE_LAYERS)}")
    if access_label not in ACCESS_LABELS:
        raise ValueError(f"source {sid}: access_label {access_label!r}")
    if credibility not in CREDIBILITY_LABELS:
        raise ValueError(f"source {sid}: credibility {credibility!r}")
    if predictive_state not in PREDICTIVE_STATES:
        raise ValueError(f"source {sid}: predictive_state {predictive_state!r}")
    return {"id": sid, "label": label, "layer": layer, "roots": _seq(roots),
            "queries": _seq(queries), "languages": _seq(languages),
            "access_label": access_label, "credibility": credibility,
            "predictive_state": predictive_state,
            "machine_use_allowed": bool(machine_use_allowed), "licence": licence, "notes": notes}


def absent_layer(layer: str, reason: str) -> dict[str, Any]:
    """A layer this region has nothing in at all, declared BY NAME with the reason (L1.28a)."""
    if layer not in SOURCE_LAYERS:
        raise ValueError(f"absent layer {layer!r}")
    return {"id": f"absent_{layer}", "label": f"NO SOURCE IN THIS LAYER: {layer}", "layer": layer,
            "roots": (), "queries": (), "languages": (), "access_label": "ACCESS_UNCLEAR",
            "credibility": "UNKNOWN", "predictive_state": "UNTESTED",
            "machine_use_allowed": False, "licence": "n/a",
            "notes": f"DECLARED ABSENT, NOT BLANK: {reason}"}


