#: A FLAT VIEW OF THE SAME REFUSALS for the framework and the fence: "<jurisdiction>:<layer>".
#: Fifteen refusals across five jurisdictions, six of them Eritrea's, and every one with a named
#: substitute -- which is what separates a measured refusal from an unread ground.
JURISDICTION_LAYER_GAPS: tuple[dict[str, str], ...] = tuple(
    {"id": f"{row['jurisdiction']}:{row['layer']}", "jurisdiction": row["jurisdiction"],
     "layer": row["layer"], "reason": row["reason"], "substitute": row["substitute"]}
    for row in NO_LAWFUL_GROUND)

