#: assumed. NOTHING here touches any entity's private systems and nothing bypasses an access
#: control: every source in this file is PUBLIC. Sanctions constrain TRANSACTIONS, not the reading
#: of published statistics -- and the desk executes only broker symbols and never an instrument
#: of any of these five countries.
