def chokepoint_phase(day: date) -> str:
    """Which phase of the Bab el-Mandeb disruption a date sits in.

    Five phases, because the mechanism changed three times: an attack that was a shipping
    incident, a network routing decision that was a commercial commitment, a military escalation
    that made the diversion sustained, and an announced truce that did NOT restore transits --
    which is the most informative of the four, because it measures how costly reversal is.
    """
    if day < CRISIS_START:
        return "PRE_CRISIS"
    if day < CARRIER_SUSPENSION:
        return "ATTACKS_BEGIN"
    if day < SUSTAINED_DIVERSION:
        return "CARRIER_SUSPENSION"
    if day < ANNOUNCED_TRUCE:
        return "SUSTAINED_DIVERSION"
    return "ANNOUNCED_TRUCE_LOW_RETURN"


def panama_constrained(day: date) -> bool:
    """True when the CONTROL chokepoint was also constrained on that date.

    A cell conditioned on Bab el-Mandeb alone cannot tell a chokepoint effect from a Red Sea
    effect. This function is how a miner asks whether the second, unrelated constraint was
    binding in the same week, and it is the identification the whole pack rests on.
    """
    return bool(PANAMA_CONTROL["start"] <= day <= PANAMA_CONTROL["end"])


def war_risk_regime(day: date) -> str:
    """The war-risk premium regime on a date, at PUBLIC-COMMENTARY evidence weight.

    BASELINE is a few hundredths of a percent of hull value; the ESCALATION and PLATEAU regimes
    were widely reported at roughly 0.7-1.0%. These are market reports and not fixings, and the
    function returns a REGIME LABEL rather than a number for exactly that reason.
    """
    if day < CRISIS_START:
        return "BASELINE"
    if day < SUSTAINED_DIVERSION:
        return "ESCALATION"
    if day < ANNOUNCED_TRUCE:
        return "PLATEAU"
    return "DECAY"


def rial_regime(day: date) -> str:
    """Yemen's monetary regime on a date: UNIFIED, SPLIT_ADMINISTRATION or TWO_BANKNOTE_SERIES.

    The spread between the Aden and Sana'a quotes only EXISTS in the third regime. A two-rate
    cell compiled on data before 2019-12-18 is compiled on a series that did not exist, and this
    function is what stops that.
    """
    if day < CBY_RELOCATION:
        return "UNIFIED"
    if day < BANKNOTE_BAN:
        return "SPLIT_ADMINISTRATION"
    return "TWO_BANKNOTE_SERIES"


def sudan_regime(day: date) -> str:
    """Sudan's regime on a date: MANAGED, FLOATED_PROGRAMME or WAR. Nothing may be pooled across
    2023-04-15: the gum arabic, gold and pipeline mechanisms all change regime there, and so does
    the availability of the data itself."""
    if day < SDG_FLOAT:
        return "MANAGED"
    if day < SD_WAR_START:
        return "FLOATED_PROGRAMME"
    return "WAR"


def djf_peg_deviation(rate: float) -> float:
    """Basis points of deviation from the 177.721 currency-board parity.

    The board DELIVERS the rate, so this number is the measure of stress in the ARRANGEMENT and
    not in the currency. A bureau quote a few francs away is normal friction; a persistent,
    widening deviation during a Red Sea stress episode is the falsifier that would cost this pack
    its control jurisdiction.
    """
    return (float(rate) - DJF_PEG) / DJF_PEG * 10000.0


def eid_al_adha(year: int) -> date | None:
    """The typed Eid al-Adha date for a year, or None when the pack has not typed one.

    It is TYPED and not computed, because a moon sighting is not arithmetic and six authorities
    announce it across these five countries. Returning None past the typed horizon is the honest
    answer; inventing a date would put a wrong clock on a real trade.
    """
    for day, name, _status in LUNAR_HOLIDAYS.get(int(year), ()):
        if "Eid al-Adha" in name:
            return day
    return None


def hajj_livestock_window(year: int) -> tuple[date, date] | None:
    """The Somali livestock shipping season for a year: the eight-week build before Eid al-Adha
    and the three days after it.

    THE WINDOW MOVES ABOUT ELEVEN DAYS EARLIER EACH GREGORIAN YEAR because the Islamic year is
    shorter, which is why a calendar-month seasonal adjustment removes the wrong thing here and
    why this is a function of the FEAST and not of the month.
    """
    feast = eid_al_adha(year)
    if feast is None:
        return None
    return feast - timedelta(days=56), feast + timedelta(days=3)


def livestock_season_phase(day: date) -> str:
    """Where a date sits in the Hajj-anchored livestock cycle: PEAK_BUILD, POST_FEAST_TROUGH or
    OFF_SEASON. Checks the neighbouring years too, because a window that opens in April can be
    anchored to a feast in a year the date does not belong to as the feast walks backwards."""
    for year in (day.year, day.year - 1, day.year + 1):
        window = hajj_livestock_window(year)
        if window is None:
            continue
        start, end = window
        if start <= day <= end:
            return "PEAK_BUILD" if day < end - timedelta(days=3) else "POST_FEAST_TROUGH"
        feast = eid_al_adha(year)
        if feast is not None and feast < day <= feast + timedelta(days=21):
            return "POST_FEAST_TROUGH"
    return "OFF_SEASON"


def gum_arabic_season(day: date) -> str:
    """The Sudanese gum arabic phase on a date: TAPPING, MAIN_AUCTION, SHIPPING_TAIL or
    OFF_SEASON.

    Tapping runs from October, the auction and marketing season from December to April, and the
    shipping tail into May; the belt is idle through the rains. A study that buckets gum arabic
    by calendar year splits every season in half, exactly as a coffee crop year does.
    """
    month = day.month
    if month in (10, 11):
        return "TAPPING"
    if month in (12, 1, 2, 3, 4):
        return "MAIN_AUCTION"
    if month == 5:
        return "SHIPPING_TAIL"
    return "OFF_SEASON"


def gum_season_year(day: date) -> int:
    """The gum arabic season a date belongs to, named by the YEAR THE TAPPING OPENED. A February
    session belongs to the season that opened the previous October, and bucketing by calendar
    year splits every season in two."""
    return day.year if day.month >= 10 else day.year - 1


def jurisdiction_of_domain(domain_id: str) -> tuple[str, ...]:
    """Which of the five a domain belongs to. A regional domain names all five."""
    return DOMAIN_JURISDICTION.get(str(domain_id), JURISDICTIONS)


#: Which jurisdiction owns each domain, so a test can prove the pack owes each of the five at
#: least two domains of its own rather than five countries' worth of one country's mechanisms.
DOMAIN_JURISDICTION: dict[str, tuple[str, ...]] = {
    "RS-A": ("ye", "dj", "er", "so"), "RS-B": ("ye", "dj", "sd", "er", "so"),
    "RS-C": ("ye", "so"), "RS-D": ("ye", "dj"),
    "RS-E": ("ye",), "RS-F": ("ye",), "RS-G": ("ye",),
    "RS-H": ("dj",), "RS-I": ("dj",),
    "RS-J": ("sd",), "RS-K": ("sd",), "RS-L": ("sd",),
    "RS-M": ("er",), "RS-N": ("er",),
    "RS-O": ("so",), "RS-P": ("so",), "RS-Q": ("so",),
    "RS-R": ("ye", "dj", "sd", "er", "so"),
}
#: Which jurisdiction each actor belongs to, by position in ACTORS. Four Yemeni, four Djiboutian,
#: four Sudanese, three Eritrean, four Somali and three regional -- the floor the brief sets is
#: three per jurisdiction, and Eritrea reaches exactly three because there are only three actors
#: in that economy whose behaviour is published at all.
ACTOR_JURISDICTION: tuple[str, ...] = (
    "ye", "ye", "ye", "ye",
    "dj", "dj", "dj", "dj",
    "sd", "sd", "sd", "sd",
    "er", "er", "er",
    "so", "so", "so", "so",
    "regional", "regional", "regional",
)
#: The mechanism family and the horizon each domain mints its cells under.
DOMAIN_MECHANISM: dict[str, str] = {
    "RS-A": "chokepoint", "RS-B": "transfer", "RS-C": "event_reaction",
    "RS-D": "release_surprise", "RS-E": "capital_control_stress", "RS-F": "supply_shock",
    "RS-G": "physical_flow", "RS-H": "control", "RS-I": "chokepoint",
    "RS-J": "supply_shock", "RS-K": "supply_shock", "RS-L": "administered_price",
    "RS-M": "physical_flow", "RS-N": "residual", "RS-O": "event_reaction",
    "RS-P": "seasonal_flow", "RS-Q": "capacity_ramp", "RS-R": "holiday_liquidity",
}
DOMAIN_HORIZON: dict[str, str] = {
    "RS-A": "2 to 12 weeks", "RS-B": "1 to 3 quarters", "RS-C": "0 to 10 sessions",
    "RS-D": "1 to 2 quarters", "RS-E": "2 to 8 weeks", "RS-F": "1 to 2 quarters",
    "RS-G": "4 to 12 weeks", "RS-H": "0 to 4 weeks", "RS-I": "1 to 2 quarters",
    "RS-J": "1 to 3 seasons", "RS-K": "1 to 2 quarters", "RS-L": "1 to 4 quarters",
    "RS-M": "1 to 2 quarters", "RS-N": "1 to 4 quarters", "RS-O": "0 to 10 sessions",
    "RS-P": "0 to 8 weeks", "RS-Q": "1 to 4 quarters", "RS-R": "0 to 2 sessions",
}


def cells() -> tuple[dict[str, Any], ...]:
    """THE TESTABLE CELLS THIS PACK MINTS: every domain crossed with its OWN instruments and its
    OWN named conditions, and nothing else.

    This is deliberately NOT a cartesian product of eighteen domains against twenty-one
    instruments, which would be 378 cells the data plane cannot fill. A cell is only worth a
    trial if this pack's own series can evaluate its CONDITION on that SYMBOL, so the cross
    product is taken INSIDE each domain, where the instruments were chosen for the mechanism and
    the conditions are states the pack's own data can resolve. That is the difference between
    maximising cells and maximising noise: a blown-up grid spends the program's shared
    family-wise error budget on cells nobody can fill, and every FX and metals cell on the desk
    pays for it (two-lane order, 2026-09-06).
    """
    out: list[dict[str, Any]] = []
    for dom in DOMAINS:
        did = str(dom["id"])
        controls = tuple(dom["controls"])
        for symbol in dom["instruments"]:
            for i, condition in enumerate(dom["conditions"]):
                out.append({
                    "cell_id": f"{CODE}:{did}:{symbol}:c{i}",
                    "domain": did,
                    "jurisdictions": DOMAIN_JURISDICTION.get(did, JURISDICTIONS),
                    "symbol": str(symbol),
                    "condition": str(condition),
                    "mechanism_family": DOMAIN_MECHANISM.get(did, "residual"),
                    "horizon": DOMAIN_HORIZON.get(did, "1 to 2 quarters"),
                    "control": controls[i % len(controls)] if controls else "",
                    "why": f"{dom['title']} -- conditioned on {condition}",
                })
    return tuple(out)


CELLS: tuple[dict[str, Any], ...] = cells()


# --------------------------------------------------------------------------- the department
def _now() -> str:
    return datetime.now(tz=UTC).isoformat(timespec="seconds")


def _emit(ctx: Any, rows: list[dict[str, Any]]) -> int:
    """Hand rows to the department Ctx when one is given, and count what was taken.

    `mine()` must work with NO context at all -- that is how a test calls it and how a fresh
    session checks the pack without wiring anything -- so an absent ctx is a normal return and
    never an error.
    """
    if ctx is None:
        return 0
    record = getattr(ctx, "record", None)
    if not callable(record):
        return 0
    taken = 0
    for row in rows:
        try:
            record(row)
        except Exception:                      # a ctx that refuses a row is the ctx's business
            continue
        taken += 1
    return taken


def mine_chokepoint_phases(pack: Any = None, ctx: Any = None) -> dict[str, Any]:
    """RS-A, RS-B and RS-D: the dated chokepoint boundaries, ALWAYS with the Panama control.

    Every row carries `panama_constrained`, because the whole identification of this pack is that
    a second great chokepoint was constrained in the same eighteen months by drought. A row that
    did not carry it would be a Red Sea claim that cannot be told from a chokepoint claim.
    """
    rows = [{"kind": "hypothesis", "pack": CODE, "domain": "RS-A", "at": day.isoformat(),
             "what": what, "where": where, "status": status,
             "phase": chokepoint_phase(day),
             "panama_constrained": panama_constrained(day),
             "war_risk_regime": war_risk_regime(day),
             "symbols": ["XBRUSD", "XTIUSD", "XNGUSD"],
             "family": "chokepoint", "horizon": "2 to 12 weeks",
             "control": PANAMA_CONTROL["why"]}
            for day, what, where, status in CHOKEPOINT_EVENTS]
    rows.append({"kind": "hypothesis", "pack": CODE, "domain": "RS-B", "at": _now(),
                 "what": "the Cape of Good Hope transit count rising while the Bab el-Mandeb "
                         "count falls, with the tonne-mile estimate rising against both -- the "
                         "signature of a REROUTE rather than of demand destruction",
                 "symbols": ["XBRUSD", "XTIUSD", "USDZAR"], "family": "transfer",
                 "horizon": "1 to 3 quarters",
                 "control": "the same instruments across the PANAMA constraint, where voyages "
                            "also lengthened and no war-risk premium was charged, which "
                            "separates DISTANCE from DANGER"})
    rows.append({"kind": "hypothesis", "pack": CODE, "domain": "RS-D", "at": _now(),
                 "what": "the Suez Canal Authority's monthly transit and revenue print as the "
                         "counterparty measurement of the strait's own count",
                 "symbols": ["EUSTX50", "GER40", "XBRUSD"], "family": "release_surprise",
                 "horizon": "1 to 2 quarters", "needs_sibling_pack": "eg",
                 "control": "the `eg` pack's own balance-of-payments canal line, and PANAMA's "
                            "revenue series; neither pack may measure the canal alone"})
    return {"miner": "rs_chokepoint_phases", "code": CODE, "at": _now(), "rows": rows,
            "emitted": _emit(ctx, rows),
            "unmeasured": ["the PortWatch series is REVISED as AIS gaps are backfilled, so a "
                           "cell compiled on today's vintage for a 2024 decision is using "
                           "information the decision did not have"]}


def mine_war_risk_cost(pack: Any = None, ctx: Any = None) -> dict[str, Any]:
    """RS-C and RS-O: the premium as a dated cost series, with piracy kept APART from stand-off
    attack rather than pooled into 'risk'."""
    regimes = ("BASELINE", "ESCALATION", "PLATEAU", "DECAY")
    anchors = (CRISIS_START - timedelta(days=1), CRISIS_START, SUSTAINED_DIVERSION,
               ANNOUNCED_TRUCE)
    rows: list[dict[str, Any]] = [
        {"kind": "hypothesis", "pack": CODE, "domain": "RS-C", "at": day.isoformat(),
         "what": f"the war-risk premium regime becomes {regime}", "regime": regime,
         "panama_constrained": panama_constrained(day),
         "symbols": ["XBRUSD", "XTIUSD", "XNGUSD"], "family": "event_reaction",
         "horizon": "0 to 10 sessions",
         "evidence_weight": "PUBLIC MARKET COMMENTARY, not a licensed feed or a fixing",
         "control": "PANAMA, where voyages lengthened and NO premium was charged at all"}
        for day, regime in zip(anchors, regimes, strict=True)]
    rows.append({"kind": "hypothesis", "pack": CODE, "domain": "RS-O", "at": _now(),
                 "what": "piracy and stand-off attack are DIFFERENT mechanisms with different "
                         "geographies, seasonality and insurance responses, and they overlapped "
                         "in time from late 2023 -- a study that pools them is pooling two",
                 "symbols": ["XBRUSD", "XTIUSD"], "family": "event_reaction",
                 "horizon": "0 to 10 sessions",
                 "control": "the 2008-2012 pure-piracy era, when no stand-off attack risk "
                            "existed at all; the monsoon window, which gates one mechanism and "
                            "not the other"})
    return {"miner": "rs_war_risk_cost", "code": CODE, "at": _now(), "rows": rows,
            "emitted": _emit(ctx, rows),
            "unmeasured": ["the premium LEVEL is a reported range and not a quoted series; no "
                           "cell is promoted on the level without the dated notice that moved it"]}


