def mine_currency_board_null(pack: Any = None, ctx: Any = None) -> dict[str, Any]:
    """RS-H and RS-I: the longest null in the pack, mined deliberately.

    A rate that has not moved since 1973 is worth more as a CONTROL than any of the four moving
    rates in this pack is worth as a signal, and this miner exists to say so in a row the
    registry can read.
    """
    rows: list[dict[str, Any]] = [
            {"kind": "hypothesis", "pack": CODE, "domain": "RS-H", "at": _now(),
             "what": "a basin stress episode in which the Yemeni spread, the Sudanese gap and "
                     "the chokepoint phase all move while the Djibouti franc CANNOT -- so the "
                     "common component is the dollar, freight or a global real shock",
             "peg": DJF_PEG, "deviation_bp_at_peg": djf_peg_deviation(DJF_PEG),
             "symbols": ["EURUSD", "USDZAR", "XBRUSD"], "family": "control",
             "horizon": "0 to 4 weeks",
             "control": "other long-lived currency boards outside this basin, which separate 'a "
                        "board' from 'this board'"},
            {"kind": "hypothesis", "pack": CODE, "domain": "RS-H", "at": _now(),
             "what": "the STRATEGIC RENT channel, which is the one positive-sign local effect in "
                     "this pack: a constrained strait raises naval presence, logistics and "
                     "basing demand in Djibouti even as it costs its neighbours",
             "symbols": ["EURUSD", "USDZAR"], "family": "control", "horizon": "1 to 4 quarters",
             "control": "Djiboutian fiscal revenue and port activity in matched non-disruption "
                        "years"},
            {"kind": "hypothesis", "pack": CODE, "domain": "RS-I", "at": _now(),
             "what": "Djibouti port throughput and its Ethiopian transit share as a proxy for "
                     "Ethiopian import demand, which Ethiopia's own statistics deliver late",
             "symbols": ["XCUUSD", "WHEAT", "CORN"], "family": "chokepoint",
             "horizon": "1 to 2 quarters", "needs_sibling_pack": "east_africa",
             "control": "BERBERA over the same quarters: a fall here that appears as a rise "
                        "there is a ROUTING event and carries no demand information, and neither "
                        "pack can establish that alone"}]
    return {"miner": "rs_currency_board_null", "code": CODE, "at": _now(), "rows": rows,
            "emitted": _emit(ctx, rows),
            "unmeasured": ["the currency-board COVER RATIO publishes annually at best and the "
                           "bureau-quote deviation is not published at all; the deviation series "
                           "is UNMEASURED and is the falsifier that would cost this pack its "
                           "control jurisdiction"]}


