def mine_eritrea_substitutes(pack: Any = None, ctx: Any = None) -> dict[str, Any]:
    """RS-M and RS-N: the six declared absences and their NAMED LAWFUL SUBSTITUTES.

    This miner's job is a COVERAGE MEASUREMENT and not a hypothesis hunt: it reports which layer
    is absent for Eritrea, what carries the information instead, and leaves everything the
    substitutes cannot read as UNMEASURED by name.
    """
    rows: list[dict[str, Any]] = [
        {"kind": "hypothesis", "pack": CODE, "domain": "RS-N", "at": _now(),
         "jurisdiction": row["jurisdiction"], "layer": row["layer"],
         "what": f"NO LAWFUL GROUND in the {row['layer']} layer for {row['jurisdiction']}; the "
                 f"named substitute is carried instead",
         "reason": row["reason"], "substitute": row["substitute"],
         "symbols": ["XZNUSD", "XCUUSD"], "family": "residual", "horizon": "1 to 4 quarters",
         "control": "the SAME substitutes applied to Djibouti, which DOES publish, so the "
                    "night-light and mirror methods are calibrated against a known series before "
                    "they are trusted on a country with none"}
        for row in NO_LAWFUL_GROUND if row["jurisdiction"] == "er"]
    rows.append({"kind": "hypothesis", "pack": CODE, "domain": "RS-M", "at": _now(),
                 "what": "Bisha concentrate tonnage in the operators' exchange filings against "
                         "Chinese and Emirati MIRROR imports -- the only quantified physical "
                         "flow Eritrea has, published because a FOREIGN listing rule compels it",
                 "symbols": ["XZNUSD", "XCUUSD", "XAUUSD"], "family": "physical_flow",
                 "horizon": "1 to 2 quarters",
                 "control": "other single-asset zinc and copper concentrate producers over the "
                            "same quarters, which separate 'Eritrea' from 'concentrate supply'"})
    return {"miner": "rs_eritrea_substitutes", "code": CODE, "at": _now(), "rows": rows,
            "emitted": _emit(ctx, rows),
            "unmeasured": ["THE NAKFA HAS NO PUBLISHED MARKET RATE AT ALL and this pack refuses "
                           "to treat a reported street rate as a price; the Eritrean exchange "
                           "rate is UNMEASURED and that is a verdict, not a gap (L1.28a)",
                           "no Eritrean CPI, national accounts, budget or reserve series exists "
                           "to be read at any frequency"]}


def mine_hajj_livestock_clock(pack: Any = None, ctx: Any = None) -> dict[str, Any]:
    """RS-P and RS-Q: the eight-week build before Eid al-Adha, bucketed by the HIJRI offset with
    the solar month as the placebo -- which is the whole test."""
    rows: list[dict[str, Any]] = []
    for year in HOLIDAYS_RULE["years"]:
        window = hajj_livestock_window(year)
        feast = eid_al_adha(year)
        if window is None or feast is None:
            continue
        start, end = window
        rows.append({"kind": "hypothesis", "pack": CODE, "domain": "RS-P",
                     "at": start.isoformat(), "window_end": end.isoformat(),
                     "feast": feast.isoformat(),
                     "what": "the Somali and Somaliland livestock shipping season builds for "
                             "eight weeks into Eid al-Adha and collapses within days after it",
                     "phase_at_open": livestock_season_phase(start),
                     "symbols": ["CORN", "SOYBEAN", "WHEAT"], "family": "seasonal_flow",
                     "horizon": "0 to 8 weeks", "needs_sibling_pack": "sa",
                     "control": "THE SOLAR MONTH ITSELF as the placebo: if the effect survives a "
                                "calendar-month control but dies against a Hijri-offset control, "
                                "the seasonal is the month and not the feast"})
    rows.append({"kind": "hypothesis", "pack": CODE, "domain": "RS-Q", "at": "2024-01-01",
                 "what": "the Ethiopia-Somaliland memorandum on port and coastal access -- a "
                         "dated geopolitical event with a physical test, because a memorandum is "
                         "not a berth",
                 "symbols": ["CORN", "WHEAT", "XCUUSD"], "family": "capacity_ramp",
                 "horizon": "1 to 4 quarters", "needs_sibling_pack": "east_africa",
                 "control": "DJIBOUTI'S THROUGHPUT over the same months: a rise at Berbera "
                            "matched by a fall at Djibouti is routing and carries no demand "
                            "information"})
    return {"miner": "rs_hajj_livestock_clock", "code": CODE, "at": _now(), "rows": rows,
            "emitted": _emit(ctx, rows),
            "unmeasured": ["Eid al-Adha is TYPED and not computed because a moon sighting is not "
                           "arithmetic; the 2026 row is PROJECTED and may be a day off, and six "
                           "authorities announce it across these five countries",
                           "livestock head counts publish seasonally and irregularly; a missing "
                           "season is UNMEASURED and the window is not imputed"]}


def mine_split_week_calendar(pack: Any = None, ctx: Any = None) -> dict[str, Any]:
    """RS-R: five national calendars, TWO WEEKEND CONVENTIONS and six sighting authorities.

    The rows that matter are the days on which only SOME of the five are at work, because that is
    where a naive Saturday-Sunday weekend assumption produces a systematically wrong sample.
    """
    rows: list[dict[str, Any]] = []
    for year in HOLIDAYS_RULE["years"]:
        for day, label in market_holidays(year).items():
            closers = tuple(sorted(c for c, fn in JURISDICTION_HOLIDAY_FN.items()
                                   if day in fn(year)))
            rows.append({"kind": "hypothesis", "pack": CODE, "domain": "RS-R",
                         "at": day.isoformat(), "closed": closers,
                         "at_work": working_jurisdictions(day),
                         "regional": len(closers) == len(JURISDICTIONS),
                         "label": label,
                         "symbols": ["XBRUSD", "XAUUSD", "WHEAT"],
                         "family": "holiday_liquidity", "horizon": "0 to 2 sessions",
                         "control": "the matched weekday twenty-six weeks away, which holds the "
                                    "solar season and moves the lunar one; days on which only "
                                    "ERITREA was at work against days on which only the other "
                                    "four were"})
    return {"miner": "rs_split_week_calendar", "code": CODE, "at": _now(), "rows": rows,
            "emitted": _emit(ctx, rows),
            "unmeasured": ["every Islamic row for 2026 is PROJECTED and six authorities announce "
                           "independently -- Aden and Sana'a have declared Eid on DIFFERENT DAYS "
                           "inside one country -- so a projected date may be right in some of "
                           "the five and a day off in the others"]}


def mine_transmission_seeds(pack: Any = None, ctx: Any = None) -> dict[str, Any]:
    """The pack's own transmission map, as HYPOTHESIS discoveries the registry deduplicates."""
    rows = [{"kind": "hypothesis", "pack": CODE, "domain": "transmission", "at": _now(),
             "edge": str(seed["id"]), "what": str(seed["mechanism"]),
             "symbols": list(seed["targets"]), "family": "transfer",
             "horizon": str(seed["horizon"]), "evidence": str(seed["evidence"]),
             "control": str(seed["control"]), "falsifier": str(seed["falsifier"])}
            for seed in TRANSMISSION_EDGES_SEED]
    return {"miner": "rs_transmission_seeds", "code": CODE, "at": _now(), "rows": rows,
            "emitted": _emit(ctx, rows), "unmeasured": []}


MINERS: dict[str, Any] = {
    "mine_chokepoint_phases": mine_chokepoint_phases,
    "mine_war_risk_cost": mine_war_risk_cost,
    "mine_two_rial_spread": mine_two_rial_spread,
    "mine_currency_board_null": mine_currency_board_null,
    "mine_sudan_supply_chains": mine_sudan_supply_chains,
    "mine_eritrea_substitutes": mine_eritrea_substitutes,
    "mine_hajj_livestock_clock": mine_hajj_livestock_clock,
    "mine_split_week_calendar": mine_split_week_calendar,
    "mine_transmission_seeds": mine_transmission_seeds,
}


def mine(ctx: Any = None) -> dict[str, Any]:
    """THE DEPARTMENT ENTRY. Pure Python, no network, no LLM and no heavy import.

    It runs the pack's own nine miners over the pack's own tables, emits through the department
    Ctx when one is given, and returns a plain report when one is not -- which is how a test
    calls it and how a fresh session checks the pack with nothing wired.
    """
    rows: list[dict[str, Any]] = []
    unmeasured: list[str] = []
    emitted = 0
    for name, fn in MINERS.items():
        try:
            got = fn(None, ctx)
        except Exception as exc:               # a broken miner is NAMED, never silently skipped
            unmeasured.append(f"{name}: raised {type(exc).__name__}: {exc}")
            continue
        rows.extend(got.get("rows", ()))
        unmeasured.extend(got.get("unmeasured", ()))
        emitted += int(got.get("emitted", 0))
    coverage = source_layer_coverage()
    return {"code": CODE, "jurisdictions": JURISDICTIONS, "at": _now(), "emitted": emitted,
            "rows": rows, "unmeasured": unmeasured,
            "cells_emitted": len(cells()),
            "miners": tuple(MINERS),
            "layers_covered": coverage["n_layers_covered"],
            "sources": coverage["n_sources"],
            "datasets": len(DATASETS), "actors": len(ACTORS), "domains": len(DOMAINS),
            "edges": len(TRANSMISSION_EDGES_SEED), "eras": len(POLICY_ERAS),
            "interactions": tuple(str(r["with"]) for r in INTERACTIONS),
            "no_lawful_ground": tuple(f"{r['jurisdiction']}:{r['layer']}"
                                      for r in NO_LAWFUL_GROUND),
            "control_chokepoint": str(PANAMA_CONTROL["chokepoint"])}


# --------------------------------------------------------------------------- assembly
_PACK_FIELDS: tuple[str, ...] = (
    "code", "name", "region_command", "currency", "executable_instruments", "central_bank",
    "fixing_conventions", "settlement_conventions", "exchanges", "holidays_rule",
    "fiscal_year_end", "positioning_sources", "native_languages", "terminology", "source_classes",
    "datasets", "actors", "domains", "custom_miners", "transmission_edges_seed", "policy_eras")


def as_dict() -> dict[str, Any]:
    """The pack as a plain mapping: the framework fields plus everything the framework has no
    slot for, carried beside them so nothing is silently dropped."""
    return {
        "code": CODE, "name": NAME, "region_command": REGION_COMMAND, "currency": CURRENCY,
        "currencies": CURRENCIES, "jurisdictions": JURISDICTIONS,
        "executable_instruments": EXECUTABLE_INSTRUMENTS, "central_bank": CENTRAL_BANK,
        "central_banks": CENTRAL_BANKS,
        "fixing_conventions": FIXING_CONVENTIONS,
        "settlement_conventions": SETTLEMENT_CONVENTIONS, "exchanges": EXCHANGES,
        "release_classes": RELEASE_CLASSES, "session_windows": SESSION_WINDOWS,
        "holidays_rule": HOLIDAYS_RULE, "fiscal_year_end": FISCAL_YEAR_END,
        "fiscal_year_ends": FISCAL_YEAR_ENDS,
        "positioning_sources": POSITIONING_SOURCES, "native_languages": NATIVE_LANGUAGES,
        "terminology": TERMINOLOGY, "source_classes": SOURCE_CLASSES,
        "source_layers": SOURCE_LAYERS, "layer_absences": LAYER_ABSENCES,
        "no_lawful_ground": NO_LAWFUL_GROUND,
        "jurisdiction_layer_gaps": JURISDICTION_LAYER_GAPS,
        "query_territories": QUERY_TERRITORIES,
        "layer_terms": layer_terms(), "source_layer_coverage": source_layer_coverage(),
        "datasets": DATASETS, "actors": ACTORS, "domains": DOMAINS,
        "custom_miners": CUSTOM_MINERS, "miner_domains": MINER_DOMAINS,
        "transmission_edges_seed": TRANSMISSION_EDGES_SEED, "policy_eras": POLICY_ERAS,
        "transmission_targets": TRANSMISSION_TARGETS, "access_constraints": ACCESS_CONSTRAINTS,
        "interactions": INTERACTIONS, "cells": CELLS,
        "region_desk": REGION_DESK, "forest": FOREST, "cot_currency": COT_CURRENCY,
        "export_economy": EXPORT_ECONOMY, "retail_leverage_regime": RETAIL_LEVERAGE_REGIME,
        "institutional_flow_sources": INSTITUTIONAL_FLOW_SOURCES, "series": SERIES,
        "mission": MISSION, "chokepoint_events": CHOKEPOINT_EVENTS,
        "panama_control": PANAMA_CONTROL, "weekend_days": WEEKEND_DAYS,
        "working_week": WORKING_WEEK, "sighting_authorities": SIGHTING_AUTHORITIES,
        "domain_jurisdiction": DOMAIN_JURISDICTION,
    }


def _source_line(sc: Mapping[str, Any]) -> str:
    return (f"{sc['id']} :: layer={sc['layer']} :: {sc['label']} :: "
            f"roots={'; '.join(sc['roots']) or 'NONE'} :: "
            f"queries={'; '.join(sc['queries']) or 'NONE'} :: "
            f"languages={','.join(sc['languages']) or 'NONE'} :: access={sc['access_label']} :: "
            f"credibility={sc['credibility']} :: predictive={sc['predictive_state']} :: "
            f"machine_use_allowed={sc['machine_use_allowed']} :: licence={sc['licence']}")


def _source_row(sc: Mapping[str, Any]) -> dict[str, Any]:
    return {"id": sc["id"], "layer": sc["layer"], "label": sc["label"], "roots": sc["roots"],
            "languages": sc["languages"], "licence": sc["licence"], "verified": False,
            "query_terms": sc["queries"],
            "notes": (f"access_label={sc['access_label']} | credibility={sc['credibility']} | "
                      f"predictive_state={sc['predictive_state']} | "
                      f"machine_use_allowed={sc['machine_use_allowed']} | {sc['notes']}")}


def _holiday_rule_row() -> dict[str, Any]:
    """The framework's HolidayRule shape.

    `weekly_closed` is (5,) -- SATURDAY ALONE -- and that is not a simplification, it is the
    measurement: Friday is a weekend day in four of the five and a working day in Eritrea, Sunday
    is the mirror image, and Saturday is the only weekday closed in all five. The per-jurisdiction
    weekends are in the note and in `WEEKEND_DAYS`, where a miner can read them properly.
    """
    dates = sorted({d.isoformat() for y in HOLIDAYS_RULE["years"] for d in market_holidays(y)})
    fixed = sorted({f"{m:02d}-{d:02d}"
                    for rows in (FIXED_YE, FIXED_DJ, FIXED_SD, FIXED_ER, FIXED_SO)
                    for m, d, _ in rows})
    return {"dates": tuple(dates), "fixed_md": tuple(fixed),
            "weekly_closed": (UNIVERSAL_CLOSED_WEEKDAY,),
            "notes": (f"{HOLIDAYS_RULE['authority']} | WEEKENDS DIFFER: "
                      f"{HOLIDAYS_RULE['weekend']} | only Saturday is closed in all five")}


def lab_kwargs() -> dict[str, Any]:
    """The keyword set `country_lab.CountryPack` is built from, in the shapes its coercion reads
    best: sources as rows AND as tagged lines, positioning and miners as strings, the holiday
    rule as dates, absent layers as a mapping."""
    data = as_dict()
    real = [s for s in SOURCE_CLASSES if not str(s["id"]).startswith("absent_")]
    data.update({
        "code": CODE.lower(),
        "positioning_sources": tuple(str(p["name"]) for p in POSITIONING_SOURCES),
        "custom_miners": tuple(str(m["entry"]) for m in CUSTOM_MINERS),
        "source_classes": tuple(_source_line(s) for s in real),
        "sources": tuple(_source_row(s) for s in real),
        "absent_layers": dict(LAYER_ABSENCES),
        "holidays_rule": _holiday_rule_row(),
    })
    return data


def pack() -> Any:
    """`country_lab.CountryPack` when the framework is present, else the mapping. Imported lazily
    so this department stays importable on a tree where the framework is not."""
    data = lab_kwargs()
    try:
        from libs.research import country_lab
    except ImportError:
        return data
    cls = getattr(country_lab, "CountryPack", None)
    if cls is None:
        return data
    try:
        import dataclasses
        names = {f.name for f in dataclasses.fields(cls)}
    except Exception:
        names = set(_PACK_FIELDS)
    try:
        return cls(**{k: v for k, v in data.items() if k in names})
    except (TypeError, ValueError):
        return data
